// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {RewardVault} from "../src/RewardVault.sol";

contract InvMutTest is Test {
    RewardVault c;
    function setUp() public { c = new RewardVault(); }

    function testFuzz_property(address user1, address user2, uint256 deposit1, uint256 deposit2, uint256 timestamp) public {
        vm.assume(user1 != address(0) && user2 != address(0));
        vm.assume(user1 != user2);
        deposit1 = bound(deposit1, 0, 100 ether);
        deposit2 = bound(deposit2, 0, 100 ether);

        vm.deal(user1, deposit1);
        vm.prank(user1);
        c.deposit{value: deposit1}();

        vm.deal(user2, deposit2);
        vm.prank(user2);
        c.deposit{value: deposit2}();

        uint256 rate1 = c.rateSnapshot(user1);
        uint256 rate2 = c.rateSnapshot(user2);

        vm.prank(user1);
        c.claim();
        vm.prank(user2);
        c.claim();

        uint256 totalRewards = c.reward(user1) + c.reward(user2);
        uint256 expectedTotal = deposit1 * rate1 + deposit2 * rate2;

        assertTrue(totalRewards == expectedTotal);
    }
}
